ALTER TABLE public.portal_announcements ADD COLUMN sample_user_id uuid, ADD COLUMN sample_at timestamptz;
COMMENT ON COLUMN public.portal_announcements.sample_user_id IS 'Optional single-account draft preview recipient; does not publish to other contractors.';
DROP POLICY announcement_contractor_read ON public.portal_announcements;
CREATE POLICY announcement_contractor_read ON public.portal_announcements FOR SELECT TO authenticated USING ((published_at IS NOT NULL OR (sample_at IS NOT NULL AND sample_user_id=auth.uid())) AND EXISTS (SELECT 1 FROM public.contractor_portal_users WHERE user_id=auth.uid() AND disabled_at IS NULL));
DROP POLICY announcement_files_read ON public.portal_announcement_files;
CREATE POLICY announcement_files_read ON public.portal_announcement_files FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.portal_announcements a WHERE a.id=announcement_id AND (a.published_at IS NOT NULL OR (a.sample_at IS NOT NULL AND a.sample_user_id=auth.uid()))) AND EXISTS (SELECT 1 FROM public.contractor_portal_users WHERE user_id=auth.uid() AND disabled_at IS NULL));
DROP POLICY announcement_reads_insert ON public.portal_announcement_reads;
CREATE POLICY announcement_reads_insert ON public.portal_announcement_reads FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND EXISTS (SELECT 1 FROM public.portal_announcements a WHERE a.id=announcement_id AND coalesce(a.published_at,a.sample_at)=portal_announcement_reads.published_at AND (a.published_at IS NOT NULL OR (a.sample_at IS NOT NULL AND a.sample_user_id=auth.uid()))) AND EXISTS (SELECT 1 FROM public.contractor_portal_users WHERE user_id=auth.uid() AND disabled_at IS NULL));
DROP POLICY announcement_storage_read ON storage.objects;
CREATE POLICY announcement_storage_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id='portal-announcements' AND EXISTS (SELECT 1 FROM public.portal_announcement_files f JOIN public.portal_announcements a ON a.id=f.announcement_id WHERE f.path=name AND (a.published_at IS NOT NULL OR (a.sample_at IS NOT NULL AND a.sample_user_id=auth.uid()))) AND EXISTS (SELECT 1 FROM public.contractor_portal_users WHERE user_id=auth.uid() AND disabled_at IS NULL));